 20→function createMessageEl(role, text) {
 21→  const msg = document.createElement("div");
 22→  msg.className = `sd-message sd-message--${role}`;
 23→
 24→  if (role !== "system") {
 25→    const label = document.createElement("span");
 26→    label.className = "sd-message__label";
 27→    label.textContent = role === "user" ? "You" : "Agent";
 28→    msg.appendChild(label);
 29→  }
 30→
 31→  const body = document.createElement("span");
 32→  body.className = "sd-message__body";
 33→  body.textContent = text;
 34→  msg.appendChild(body);
 35→
 36→  return msg;
 37→}
