 39→/* ── WebSocket connection ─────────────────────────────────────────── */
 40→
 41→class AgentConnection {
 42→  constructor(onMessage, onStatus) {
 43→    this.ws = null;
 44→    this.onMessage = onMessage;   // (event) => void
 45→    this.onStatus = onStatus;     // (status) => void
 46→    this.reconnectDelay = 1000;
 47→    this.maxReconnectDelay = 15000;
 48→    this.currentDelay = this.reconnectDelay;
 49→    this._closed = false;
 50→    this._streamEl = null;        // element accumulating streamed text
 51→  }
 52→
 53→  connect() {
 54→    const proto = location.protocol === "https:" ? "wss:" : "ws:";
 55→    const url = `${proto}//${location.host}/superduper/ws`;
 56→
 57→    this.onStatus("connecting");
 58→    this.ws = new WebSocket(url);
 59→
 60→    this.ws.onopen = () => {
 61→      this.currentDelay = this.reconnectDelay;
 62→      this.onStatus("connected");
 63→    };
 64→
 65→    this.ws.onmessage = (evt) => {
 66→      try {
 67→        const data = JSON.parse(evt.data);
 68→        this.onMessage(data);
 69→      } catch (e) {
 70→        console.error("[SUPER DUPER] Bad message:", evt.data);
 71→      }
 72→    };
 73→
 74→    this.ws.onclose = () => {
 75→      this.onStatus("disconnected");
 76→      if (!this._closed) {
 77→        setTimeout(() => this.connect(), this.currentDelay);
 78→        this.currentDelay = Math.min(this.currentDelay * 1.5, this.maxReconnectDelay);
 79→      }
 80→    };
 81→
 82→    this.ws.onerror = (err) => {
 83→      console.error("[SUPER DUPER] WebSocket error:", err);
 84→    };
 85→  }
 86→
 87→  send(type, payload) {
 88→    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
 89→      this.ws.send(JSON.stringify({ type, ...payload }));
 90→      return true;
 91→    }
 92→    return false;
 93→  }
 94→
 95→  close() {
 96→    this._closed = true;
 97→    if (this.ws) this.ws.close();
 98→  }
 99→}
