 22→void
 23→HdCarWashFramebuffer::Resize(unsigned int w, unsigned int h)
 24→{
 25→    if (width == w && height == h) {
 26→        return;
 27→    }
 28→
 29→    width = w;
 30→    height = h;
 31→    size_t numPixels = static_cast<size_t>(w) * h;
 32→
 33→    color.resize(numPixels);
 34→    depth.resize(numPixels);
 35→    normal.resize(numPixels);
 36→    objectId.resize(numPixels);
 37→    primId.resize(numPixels);
 38→    motionVector.resize(numPixels);
 39→}
