 40→// =============================================================================
 41→// Base64 Encoding (for image transfer)
 42→// =============================================================================
 43→
 44→namespace {
 45→
 46→static const char base64_chars[] =
 47→    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
 48→    "abcdefghijklmnopqrstuvwxyz"
 49→    "0123456789+/";
 50→
 51→std::string Base64Encode(const std::vector<uint8_t>& data) {
 52→    std::string result;
 53→    int i = 0;
 54→    int j = 0;
 55→    uint8_t char_array_3[3];
 56→    uint8_t char_array_4[4];
 57→    size_t in_len = data.size();
 58→    const uint8_t* bytes_to_encode = data.data();
 59→
 60→    while (in_len--) {
 61→        char_array_3[i++] = *(bytes_to_encode++);
 62→        if (i == 3) {
 63→            char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
 64→            char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
 65→            char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
 66→            char_array_4[3] = char_array_3[2] & 0x3f;
 67→
 68→            for (i = 0; i < 4; i++)
 69→                result += base64_chars[char_array_4[i]];
 70→            i = 0;
 71→        }
 72→    }
 73→
 74→    if (i) {
 75→        for (j = i; j < 3; j++)
 76→            char_array_3[j] = '\0';
 77→
 78→        char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
 79→        char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
 80→        char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
 81→
 82→        for (j = 0; j < i + 1; j++)
 83→            result += base64_chars[char_array_4[j]];
 84→
 85→        while (i++ < 3)
 86→            result += '=';
 87→    }
 88→
 89→    return result;
 90→}
