 92→std::vector<uint8_t> Base64Decode(const std::string& encoded) {
 93→    std::vector<uint8_t> result;
 94→    int in_len = static_cast<int>(encoded.size());
 95→    int i = 0;
 96→    int j = 0;
 97→    int in_ = 0;
 98→    uint8_t char_array_4[4], char_array_3[3];
 99→
100→    auto is_base64 = [](unsigned char c) {
101→        return (isalnum(c) || (c == '+') || (c == '/'));
102→    };
103→
104→    auto find_char = [](char c) -> int {
105→        const char* p = strchr(base64_chars, c);
106→        return p ? static_cast<int>(p - base64_chars) : -1;
107→    };
108→
109→    while (in_len-- && encoded[in_] != '=' && is_base64(encoded[in_])) {
110→        char_array_4[i++] = encoded[in_]; in_++;
111→        if (i == 4) {
112→            for (i = 0; i < 4; i++)
113→                char_array_4[i] = static_cast<uint8_t>(find_char(char_array_4[i]));
114→
115→            char_array_3[0] = (char_array_4[0] << 2) + ((char_array_4[1] & 0x30) >> 4);
116→            char_array_3[1] = ((char_array_4[1] & 0xf) << 4) + ((char_array_4[2] & 0x3c) >> 2);
117→            char_array_3[2] = ((char_array_4[2] & 0x3) << 6) + char_array_4[3];
118→
119→            for (i = 0; i < 3; i++)
120→                result.push_back(char_array_3[i]);
121→            i = 0;
122→        }
123→    }
124→
125→    if (i) {
126→        for (j = 0; j < i; j++)
127→            char_array_4[j] = static_cast<uint8_t>(find_char(char_array_4[j]));
128→
129→        char_array_3[0] = (char_array_4[0] << 2) + ((char_array_4[1] & 0x30) >> 4);
130→        char_array_3[1] = ((char_array_4[1] & 0xf) << 4) + ((char_array_4[2] & 0x3c) >> 2);
131→
132→        for (j = 0; j < i - 1; j++)
133→            result.push_back(char_array_3[j]);
134→    }
135→
136→    return result;
137→}
