237→void WriteChunk(std::vector<uint8_t>& png, const char* type, const std::vector<uint8_t>& data) {
238→    // Length (big-endian)
239→    uint32_t len = static_cast<uint32_t>(data.size());
240→    png.push_back((len >> 24) & 0xff);
241→    png.push_back((len >> 16) & 0xff);
242→    png.push_back((len >> 8) & 0xff);
243→    png.push_back(len & 0xff);
244→
245→    // Type
246→    size_t typeStart = png.size();
247→    for (int i = 0; i < 4; i++) {
248→        png.push_back(type[i]);
249→    }
250→
251→    // Data
252→    png.insert(png.end(), data.begin(), data.end());
253→
254→    // CRC (over type + data)
255→    std::vector<uint8_t> crcData(png.begin() + typeStart, png.end());
256→    uint32_t crc = Crc32(crcData.data(), crcData.size());
257→    png.push_back((crc >> 24) & 0xff);
258→    png.push_back((crc >> 16) & 0xff);
259→    png.push_back((crc >> 8) & 0xff);
260→    png.push_back(crc & 0xff);
261→}
